WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int

	if(@diagramname is null)
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT; 
	
	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	delete from dbo.sysdiagrams where diagram_id = @DiagId;

	return 0;
END

CREATE PROCEDURE CheckBudget
    @PurchaseAmount FLOAT,
    @Result INT OUTPUT
AS
BEGIN
    DECLARE @CurrentBudget FLOAT;

    SELECT @CurrentBudget = TotalBudget
    FROM Budget
    WHERE BudgetID = 1;

    IF @CurrentBudget >= @PurchaseAmount
        SET @Result = 0;  -- денег хватает
    ELSE
        SET @Result = 1;  -- денег недостаточно
END;

CREATE PROCEDURE [dbo].[AddSale]
    @ProductID INT,
    @Quantity INT,
    @TotalAmount DECIMAL(18,2),
    @EmployeeID INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @CurrentStock FLOAT;
        DECLARE @CurrentTotal FLOAT;
        DECLARE @CostPerUnit FLOAT;
        DECLARE @TotalCost FLOAT;

        ----------------------------------------------------
        -- Получаем текущий остаток и себестоимость
        ----------------------------------------------------
        SELECT 
            @CurrentStock = Quantity,
            @CurrentTotal = TotalAmount
        FROM FinishedProducts
        WHERE ProductID = @ProductID;

        ----------------------------------------------------
        -- Проверка остатка
        ----------------------------------------------------
        IF @CurrentStock < @Quantity
        BEGIN
            RAISERROR('Недостаточно готовой продукции.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ----------------------------------------------------
        -- Расчёт себестоимости
        ----------------------------------------------------
        SET @CostPerUnit = @CurrentTotal / NULLIF(@CurrentStock,0);
        SET @TotalCost = @CostPerUnit * @Quantity;

        ----------------------------------------------------
        -- Уменьшаем склад (количество + себестоимость)
        ----------------------------------------------------
        UPDATE FinishedProducts
        SET 
            Quantity = Quantity - @Quantity,
            TotalAmount =
                CASE 
                    WHEN Quantity - @Quantity <= 0 THEN 0
                    ELSE ROUND(TotalAmount - @TotalCost, 2)
                END
        WHERE ProductID = @ProductID;

        ----------------------------------------------------
        -- Добавляем запись продажи
        ----------------------------------------------------
        INSERT INTO Sales 
            (ProductID, Quantity, TotalAmount, SaleDate, EmployeeID)
        VALUES 
            (@ProductID, @Quantity, @TotalAmount, GETDATE(), @EmployeeID);

        ----------------------------------------------------
        -- Увеличиваем бюджет
        ----------------------------------------------------
        UPDATE Budget
        SET TotalBudget = TotalBudget + @TotalAmount;

        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;

CREATE PROCEDURE AddRawMaterialPurchase
    @RawMaterialID INT,
    @Quantity FLOAT,
    @TotalAmount FLOAT,
    @EmployeeID INT,
    @Result INT OUTPUT
AS
BEGIN
    DECLARE @CheckResult INT;

    EXEC CheckBudget @TotalAmount, @CheckResult OUTPUT;

    IF @CheckResult = 0
    BEGIN
        INSERT INTO RawMaterialPurchases
        (RawMaterialID, Quantity, TotalAmount, EmployeeID)
        VALUES
        (@RawMaterialID, @Quantity, @TotalAmount, @EmployeeID);

        SET @Result = 0;
    END
    ELSE
    BEGIN
        SET @Result = 1;
    END
END;

CREATE PROCEDURE AddSalaryPayment
    @EmployeeID INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @Salary DECIMAL(18,2);
        DECLARE @CurrentBudget DECIMAL(18,2);

        -- Получаем зарплату сотрудника
        SELECT @Salary = Salary
        FROM Employees
        WHERE EmployeeID = @EmployeeID;

        IF @Salary IS NULL
        BEGIN
            RAISERROR('Сотрудник не найден.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        -- Получаем текущий бюджет
        SELECT @CurrentBudget = TotalBudget
        FROM Budget;

        -- Проверяем достаточность средств
        IF @CurrentBudget < @Salary
        BEGIN
            RAISERROR('Недостаточно средств для выплаты зарплаты.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        -- Списываем бюджет
        UPDATE Budget
        SET TotalBudget = TotalBudget - @Salary;

        -- Записываем выплату
        INSERT INTO SalaryPayments (EmployeeID, Amount)
        VALUES (@EmployeeID, @Salary);

        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
